    makeRequire({ './mergeState.js': loadModule('js/common/mergeState.js') }));

var githubHelpersModule = loadModule(
    'js/common/githubHelpers.js',
    makeRequire({
        './pullRequest.js': { buildOriginFetchCommand: function() { return 'git fetch origin'; } },
