+function postReworkStartedCommentOrSkip(prAnchor, tracker, ticketKey, customParams, prDetails, branchName, conflictFiles, failedChecks) {
+    if (prAnchor) {
+        console.log('PR-anchored rework: skipping tracker comment (no ticket, #544)');
+        return;
+    }
